def button(text, url, primary=False):
 return f'<a class="btn{" primary" if primary else ""}" href="{url}">{text} <span aria-hidden="true">↗</span></a>'

def section(body, kind=''):
 return f'<section class="section {kind}"><div class="wrap">{body}</div></section>'

def heading(kicker,title,desc=''):
 return f'<div class="section-head"><div><div class="eyebrow">{kicker}</div><h2>{title}</h2></div>{f"<p class=muted>{desc}</p>" if desc else ""}</div>'

def cards(items, two=False):
 return '<div class="grid'+(' two' if two else '')+'">'+''.join(f'<article class="card"><span class="num">0{i+1} / SAFEBOX</span><h3>{title}</h3><p class="muted">{body}</p></article>' for i,(title,body) in enumerate(items))+'</div>'

def flow():
 return '<div class="step-flow">'+''.join(f'<article class="step"><h3>{t}</h3><p>{b}</p></article>' for t,b in [('Выберите','Взрослая или семейная версия — без длинной анкеты.'),('Согласуйте','Обсудите индивидуальный список средств со специалистом.'),('Соберите','Приобретите средства и разместите их по разделам.'),('Проверьте','Покажите близким расположение аптечки и обновляйте её содержимое.')])+'</div>'

def banner():
 return section('<div class="banner"><div><h2>Подготовиться —<br>значит позаботиться.</h2><p>Начните с простого: выберите, для кого вы собираете аптечку.</p></div>'+button('Выбрать аптечку','choose.html')+'</div>','compact')

def intro(kicker,title,desc):
 return f'<div class="wrap page-head"><div class="eyebrow">{kicker}</div><h1>{title}</h1><p class="lead">{desc}</p></div>'

def faq(items):
 return '<div class="faq-group">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div>'

