 {'<label class="field">Компания<input name="company" autocomplete="organization" maxlength="150" required></label><label class="field">Регион<input name="region" maxlength="100" required></label><label class="field">Формат сотрудничества<select name="type"><option>Розничные продажи</option><option>Дистрибуция</option><option>Аптечная сеть</option><option>Корпоративные закупки</option><option>Другой формат</option></select></label>' if partner else '<label class="field">Тема<select name="type"><option>Вопрос о продукте</option><option>Покупка и запуск</option><option>Отзыв или тестирование</option><option>Забота о детях</option><option>Другое</option></select></label>'}
